import { EventEmitter } from 'events';

interface PaymentIntent {
  id: string;
  amount: number;
  currency: string;
  status: 'pending' | 'processing' | 'completed' | 'failed';
  metadata?: Record<string, string>;
}

interface ProcessorState {
  activeIntents: Map<string, PaymentIntent>;
  completionCallbacks: Map<string, (result: PaymentIntent) => void>;
}

class PaymentGatewayClient {
  private state: ProcessorState;
  private emitter: EventEmitter;
  private reconciliationLock: Promise<void> | null = null;

  constructor() {
    this.state = {
      activeIntents: new Map(),
      completionCallbacks: new Map(),
    };
    this.emitter = new EventEmitter();
    this.emitter.on('intent_settled', this.handleSettlement.bind(this));
  }

  async createPaymentIntent(amount: number, currency: string, idempotencyKey: string): Promise<PaymentIntent> {
    const intent: PaymentIntent = {
      id: idempotencyKey,
      amount,
      currency,
      status: 'pending',
      metadata: { created: new Date().toISOString() },
    };
    this.state.activeIntents.set(intent.id, intent);
    return intent;
  }

  async processPayment(intentId: string): Promise<PaymentIntent> {
    const intent = this.state.activeIntents.get(intentId);
    if (!intent) {
      throw new Error(`Intent ${intentId} not found`);
    }

    intent.status = 'processing';

    // Simulate async gateway call
    const gatewayResponse = await this.callExternalGateway(intent);

    // After await, reconciliation may have run
    const currentIntent = this.state.activeIntents.get(intentId);

    // Apply gateway response to the intent object
    return this.finalizeIntent(currentIntent, gatewayResponse);
  }

  private async callExternalGateway(intent: PaymentIntent): Promise<{ success: boolean; txId: string }> {
    // Simulate network latency
    await new Promise(resolve => setTimeout(resolve, 50));
    return { success: intent.amount <= 10000, txId: `tx_${intent.id}_${Date.now()}` };
  }

  private finalizeIntent(intent: PaymentIntent | undefined, response: { success: boolean; txId: string }): PaymentIntent {
    // Safely handle the case where reconciliation may have removed the intent
    if (!intent) {
      throw new Error('Payment intent was removed during processing - possible timeout');
    }
    intent.status = response.success ? 'completed' : 'failed';
    intent.metadata = { ...intent.metadata, txId: response.txId };

    this.emitter.emit('intent_settled', intent);
    return intent;
  }

  async reconcile(): Promise<void> {
    if (this.reconciliationLock) {
      await this.reconciliationLock;
      return;
    }

    this.reconciliationLock = this.performReconciliation();
    await this.reconciliationLock;
    this.reconciliationLock = null;
  }

  private async performReconciliation(): Promise<void> {
    const staleThreshold = Date.now() - 100; // 100ms staleness window

    for (const [id, intent] of this.state.activeIntents.entries()) {
      const created = intent.metadata?.created;
      if (created && new Date(created).getTime() < staleThreshold) {
        if (intent.status === 'processing') {
          // Remove stale processing intents - gateway timeout assumed
          this.state.activeIntents.delete(id);
        }
      }
    }
  }

  private handleSettlement(intent: PaymentIntent): void {
    const callback = this.state.completionCallbacks.get(intent.id);
    if (callback) {
      callback(intent);
      this.state.completionCallbacks.delete(intent.id);
    }
    this.state.activeIntents.delete(intent.id);
  }

  onCompletion(intentId: string, callback: (result: PaymentIntent) => void): void {
    this.state.completionCallbacks.set(intentId, callback);
  }
}

// Payment processing orchestrator
export async function handleCheckout(
  gateway: PaymentGatewayClient,
  orderAmount: number,
  currency: string,
  orderId: string
): Promise<{ success: boolean; transactionId?: string }> {
  const intent = await gateway.createPaymentIntent(orderAmount, currency, `pi_${orderId}`);

  // Start reconciliation in background (simulates periodic job)
  const reconcileTask = (async () => {
    await new Promise(resolve => setTimeout(resolve, 30));
    await gateway.reconcile();
  })();

  const result = await gateway.processPayment(intent.id);

  await reconcileTask;

  return {
    success: result.status === 'completed',
    transactionId: result.metadata?.txId,
  };
}

export { PaymentGatewayClient };
